dict.string:
// RhymeZone — rhymes from the Datamuse API (the engine behind RhymeZone).
// JavaScript for Automation ships with macOS, so there is nothing to install.

function run(argv) {
    const word = (argv[0] || '').trim()
    const items = []
    const say = (title, subtitle) => JSON.stringify({ items: [{ title, subtitle, valid: false }] })

    if (!word) return say('Type a word to find rhymes', 'Rhymes from Datamuse, the engine behind RhymeZone')

    const app = Application.currentApplication()
    app.includeStandardAdditions = true
    const quoted = "'" + word.replace(/'/g, "'\\''") + "'"

    let words
    try {
        // -f: HTTP errors fail instead of returning an error page; --max-time: never hang Alfred
        const raw = app.doShellScript('curl -s -f -G --max-time 5 https://api.datamuse.com/words' +
                                      ' --data-urlencode rel_rhy=' + quoted + ' --data max=100')
        words = JSON.parse(raw)
    } catch (e) {
        return say('Could not reach Datamuse', 'Check your connection and try again')
    }

    if (!words.length) return say('No rhymes found', `Nothing rhymes with “${word}”`)

    for (const w of words) {
        const syllables = w.numSyllables ? `${w.numSyllables} syllable${w.numSyllables === 1 ? '' : 's'}` : ''
        items.push({
            title: w.word,
            subtitle: [syllables, w.score ? `score ${w.score}` : '', '↩ copy'].filter(Boolean).join(' · '),
            arg: w.word,
            valid: true,
            text: { copy: w.word, largetype: w.word },
            quicklookurl: 'https://www.rhymezone.com/r/rhyme.cgi?typeofrhyme=perfect&Word=' + encodeURIComponent(w.word)
        })
    }
    return JSON.stringify({ items })
}
